<script lang="ts">
  /**
   * Render a LaTeX expression with KaTeX.
   *
   * KaTeX's output is generated by a trusted library, not by the model, so
   * `{@html}` is safe here — unlike model output, which is always rendered
   * from tokens. A parse failure (bad LaTeX) falls back to the raw source in
   * monospace so the reader can still see and copy what the model wrote.
   */
  import katex from "katex";

  interface Props {
    latex: string;
    displayMode?: boolean;
  }

  let { latex, displayMode = false }: Props = $props();

  const html = $derived.by(() => {
    try {
      return katex.renderToString(latex, {
        displayMode,
        throwOnError: false,
        strict: false,
        trust: false,
      });
    } catch {
      return null;
    }
  });
</script>

{#if html}
  {@html html}
{:else}
  <code class="md-math-fallback">{latex}</code>
{/if}
